create table public.anime_library ( id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, anime_id integer not null check (anime_id > 0), anime_title text not null check (char_length(trim(anime_title)) between 1 and 250), cover_url text not null default '', status text not null default 'plan_to_watch' check (status in ('watching', 'completed', 'on_hold', 'dropped', 'plan_to_watch')), episodes_watched integer not null default 0 check (episodes_watched >= 0), total_episodes integer check (total_episodes is null or total_episodes > 0), personal_rating smallint check (personal_rating is null or personal_rating between 1 and 10), started_at date, completed_at date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (user_id, anime_id), check (total_episodes is null or episodes_watched <= total_episodes) ); create index anime_library_user_status_idx on public.anime_library (user_id, status); create index anime_library_user_updated_idx on public.anime_library (user_id, updated_at desc); alter table public.anime_library enable row level security; create policy "Users can read their anime library" on public.anime_library for select to authenticated using (auth.uid() = user_id); create policy "Users can add to their anime library" on public.anime_library for insert to authenticated with check (auth.uid() = user_id); create policy "Users can update their anime library" on public.anime_library for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "Users can delete from their anime library" on public.anime_library for delete to authenticated using (auth.uid() = user_id); grant select, delete on public.anime_library to authenticated; grant insert (anime_id, anime_title, cover_url, status, episodes_watched, total_episodes, personal_rating, started_at, completed_at) on public.anime_library to authenticated; grant update (anime_title, cover_url, status, episodes_watched, total_episodes, personal_rating, started_at, completed_at) on public.anime_library to authenticated; create table public.anime_episode_history ( id uuid primary key default gen_random_uuid(), library_id uuid not null references public.anime_library(id) on delete cascade, episode_number integer not null check (episode_number > 0), watched_at timestamptz not null default now(), unique (library_id, episode_number) ); create index anime_episode_history_library_idx on public.anime_episode_history (library_id, episode_number); alter table public.anime_episode_history enable row level security; create policy "Users can read their episode history" on public.anime_episode_history for select to authenticated using ( exists ( select 1 from public.anime_library library where library.id = anime_episode_history.library_id and library.user_id = auth.uid() ) ); create policy "Users can add their episode history" on public.anime_episode_history for insert to authenticated with check ( exists ( select 1 from public.anime_library library where library.id = anime_episode_history.library_id and library.user_id = auth.uid() ) ); create policy "Users can delete their episode history" on public.anime_episode_history for delete to authenticated using ( exists ( select 1 from public.anime_library library where library.id = anime_episode_history.library_id and library.user_id = auth.uid() ) ); grant select, delete on public.anime_episode_history to authenticated; grant insert (library_id, episode_number) on public.anime_episode_history to authenticated; create table public.manga_library ( id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, manga_id integer not null check (manga_id > 0), manga_title text not null check (char_length(trim(manga_title)) between 1 and 250), cover_url text not null default '', status text not null default 'plan_to_read' check (status in ('reading', 'completed', 'on_hold', 'dropped', 'plan_to_read')), chapters_read integer not null default 0 check (chapters_read >= 0), total_chapters integer check (total_chapters is null or total_chapters > 0), volumes_read integer not null default 0 check (volumes_read >= 0), total_volumes integer check (total_volumes is null or total_volumes > 0), personal_rating smallint check (personal_rating is null or personal_rating between 1 and 10), started_at date, completed_at date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (user_id, manga_id), check (total_chapters is null or chapters_read <= total_chapters), check (total_volumes is null or volumes_read <= total_volumes) ); create index manga_library_user_status_idx on public.manga_library (user_id, status); create index manga_library_user_updated_idx on public.manga_library (user_id, updated_at desc); alter table public.manga_library enable row level security; create policy "Users can read their manga library" on public.manga_library for select to authenticated using (auth.uid() = user_id); create policy "Users can add to their manga library" on public.manga_library for insert to authenticated with check (auth.uid() = user_id); create policy "Users can update their manga library" on public.manga_library for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "Users can delete from their manga library" on public.manga_library for delete to authenticated using (auth.uid() = user_id); grant select, delete on public.manga_library to authenticated; grant insert (manga_id, manga_title, cover_url, status, chapters_read, total_chapters, volumes_read, total_volumes, personal_rating, started_at, completed_at) on public.manga_library to authenticated; grant update (manga_title, cover_url, status, chapters_read, total_chapters, volumes_read, total_volumes, personal_rating, started_at, completed_at) on public.manga_library to authenticated; create or replace function public.set_library_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = now(); return new; end; $$; revoke all on function public.set_library_updated_at() from public, anon, authenticated; create trigger anime_library_set_updated_at before update on public.anime_library for each row execute procedure public.set_library_updated_at(); create trigger manga_library_set_updated_at before update on public.manga_library for each row execute procedure public.set_library_updated_at();
